from collections import deque
def transform(grid):
    a=[row[:] for row in grid]; h=len(a); w=len(a[0]); bg=a[0][0]
    seen=set(); q=deque()
    for r in range(h):
        for c in range(w):
            if (r in (0,h-1) or c in (0,w-1)) and a[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and a[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    holes=set((r,c) for r in range(h) for c in range(w) if a[r][c]==bg and (r,c) not in seen)
    while holes:
        start=holes.pop(); comp={start}; stack=[start]
        while stack:
            r,c=stack.pop()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in holes: holes.remove((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
        fill=2 if len({r for r,c in comp})%2==0 and len({c for r,c in comp})%2==0 else 7
        for r,c in comp: a[r][c]=fill
    return a
